  const longo = await admin('POST', `${R}/comparativo/importar-csv`, { conteudo: 'codigo_ies,ano,indicador,valor,curso\n1002,2025,CPC,"3,3",Odontologia\n1002,2025,CC,4,Odontologia\n1002,2025,XYZ,1,', delimitador: ',' })
