  check('diferença para a média dos concorrentes', cpc.diferencaMedia !== null && cpc.mediaConcorrentes > 3.5)
  check('diferença para o melhor = -0,80', cpc.diferencaMelhor === -0.8, cpc.diferencaMelhor)
  const men = painel.body.indicadores.find((i: any) => i.indicador === 'MENSALIDADE')
  check('mensalidade é neutra (sem melhor/pior)', men.sentido === 'NEUTRO')
  check('anos disponíveis', painel.body.anosDisponiveis[0] === 2025 && painel.body.anosDisponiveis.includes(2024))
  const p24 = await admin('GET', `${R}/comparativo/painel?ano=2024`)
