  check('ano inválido 400', (await admin('GET', `${R}/comparativo/painel?ano=abc`)).status === 400)
  const pcurso = await admin('GET', `${R}/comparativo/painel?curso=Odontologia`)
  check('painel por curso', pcurso.status === 200 && pcurso.body.indicadores.find((i: any) => i.indicador === 'CC').participantes === 1)
  const sel = await admin('GET', `${R}/comparativo/painel?iesIds=${ies1.body.id}`)
  check('painel com IES selecionadas (inclui a própria)', sel.body.totalIes === 2)
  const evo = await admin('GET', `${R}/comparativo/evolucao?indicador=CPC`)
  check('evolução por ano', evo.status === 200 && evo.body.anos.join() === '2024,2025' && evo.body.series.length >= 4, evo.body.anos)
  check('evolução: série da própria IES', evo.body.series.find((s: any) => s.tipo === 'PROPRIA').pontos.map((p: any) => p.valor).join() === '3.4,3.7')
  check('evolução indicador inválido 400', (await admin('GET', `${R}/comparativo/evolucao?indicador=XYZ`)).status === 400)
  check('comparativo CSV', /Posição/.test((await admin('GET', `${R}/comparativo/painel?formato=csv`)).text))
  check('coord lê comparativo', (await coord('GET', `${R}/comparativo/painel`)).status === 200)
  check('coord não importa CSV', (await coord('POST', `${R}/comparativo/importar-csv`, { conteudo: csv })).status === 403)
  check('isolamento: outro tenant sem IES', (await adminB('GET', `${R}/comparativo/ies`)).body.total === 0)
  const lixo = await admin('POST', `${R}/comparativo/ies`, { nome: 'Para excluir' })
