  check('CIPA: mapa de riscos 5x5', todosPaineis.cipa.tabelas[0].linhas.length === 5 && todosPaineis.cipa.tabelas[0].linhas[1].p3 === 1)
  check('provas: 1 edição, 4 inscritos, nota média 70', k('provas', 'edicoes') === 1 && k('provas', 'inscritos') === 4 && k('provas', 'notaMedia') === 70, k('provas', 'notaMedia'))
  check('provas: simulado 60%', k('provas', 'mediaSimulados') === 60 && k('provas', 'simulados') === 2)
  check('professores: 2 aplicações; 1 oculta por baixo nº de respostas', k('professores', 'aplicacoes') === 2 && k('professores', 'suprimidas') === 1)
  check('professores: média 4,5 (escala 0-5)', k('professores', 'media') === 4.5, k('professores', 'media'))
  check('vestibular: 10 vagas, 5 inscritos, 2 matriculados', k('vestibular', 'vagas') === 10 && k('vestibular', 'inscritos') === 5 && k('vestibular', 'matriculados') === 2)
  check('vestibular: conversão 40% e CAC R$1.500', k('vestibular', 'conversao') === 40 && k('vestibular', 'cac') === 1500, [k('vestibular', 'conversao'), k('vestibular', 'cac')])
  check('publicações: 4 no total, 3 de artigo A1/B..., qualis', k('publicacoes', 'total') === 4 && k('publicacoes', 'qualis') === 1 + 1 || k('publicacoes', 'qualis') >= 1, k('publicacoes', 'total'))
  check('convênios: painel espelha o cadastro', k('convenios', 'vigentes') >= 2 && k('convenios', 'v30') >= 0)
